import{_ as i,C as n,c as s,o as r,aj as l,G as a,w as c}from"./chunks/framework.Bfdr4H5E.js";const w=JSON.parse('{"title":"Money Management","description":"","frontmatter":{"outline":"deep","prev":{"text":"Financial Survival","link":"/trading-with-pav/financial-survival"},"next":{"text":"Money Management – Trading Plan Inclusion","link":"/trading-with-pav/money-management-trading-plan-inclusion"}},"headers":[],"relativePath":"trading-with-pav/money-management.md","filePath":"trading-with-pav/money-management.md"}'),m={name:"trading-with-pav/money-management.md"};function h(u,e,d,g,p,f){const t=n("GraphComment"),o=n("ClientOnly");return r(),s("div",null,[e[0]||(e[0]=l('<h1 id="money-management" tabindex="-1">Money Management <a class="header-anchor" href="#money-management" aria-label="Permalink to &quot;Money Management&quot;">​</a></h1><p>To develop our money management plan, we’ll look at financial survival from a risk management perspective.</p><div class="tip custom-block"><p class="custom-block-title">What are the risks as a result of trading?</p><ol><li><strong>Individual Trade Risk</strong> – a single trade loss which takes our account to levels which force us to quit.</li><li><strong>Session Draw-down Risk</strong> – a single trading session which takes our account to levels which force us to quit.</li><li><strong>Business Draw-down Risk</strong> – a sequence of trade losses over a longer time-frame resulting in draw-down to levels which force us to quit.</li><li><strong>Increased Size Risk</strong> – an inability to psychologically manage the increased size as our account balance grows, leading to excessive draw-down.</li><li><strong>Insufficient Income Risk</strong> – an inability to maintain lifestyle through lack of income, forcing withdrawal of account funds and our inability to continue trading.</li></ol><p>These risks are managed through clearly defined controls within our trading plan.</p></div><p>The next article is an example trading plan inclusion. Followed by Explanatory notes article. As always, feel free to adjust as you see fit (recognizing that increased risk increases the likelihood of failure to survive the learning curve).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>You will note that my recommended levels of risk are VERY conservative.</li><li>The focus in this plan is not on capital growth, but rather on capital preservation during the learning phase.</li><li>As such, we aim to ensure a low percentage risk at all times.</li></ul></div><p>Once consistently profitable, if you wish to increase risk in search of higher gains then by all means increase the percentages, or do some further research on alternate money management strategies.</p><p>Do so at your own risk though. The focus (in my opinion) should always be more on capital preservation than on growth.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',8)),a(o,null,{default:c(()=>[a(t)]),_:1})])}const y=i(m,[["render",h]]);export{w as __pageData,y as default};
